/// A module providing merge sort implementations.
pub mod merge_sort {
    /// Sorts a slice using the merge sort algorithm and returns a new sorted vector.
    ///
    /// # Complexity
    /// - Time: O(n log n) in all cases (best, average, worst).
    /// - Space: O(n) auxiliary space for the temporary arrays used during merging.
    ///
    /// # Arguments
    /// * `v` - A slice of elements that implement `Ord` and `Clone`.
    ///
    /// # Returns
    /// A new `Vec<T>` containing the sorted elements.
    ///
    /// # Examples
    /// ```
    /// use merge_sort::merge_sort;
    ///

```nginx
# Define rate limiting zone: 10MB memory, 20 requests per second per IP
limit_req_zone $binary_remote_addr zone=api_limit:10m rate=20r/s;

# Define a log format that excludes the /health endpoint from access logs
# We use a map to determine if we should log or not
map $uri $loggable {
    default 1;
    /health 0;
}

# Create a custom log format that uses the $loggable variable
# Note: Standard nginx access_log does not directly support conditional logging via a variable in the format string easily without a map for the entire log line or using a separate log file.
# A more robust way to "exempt"

